    pre.innerHTML = d.log_tail.map(l => {
      const c = lineClass(l);
      return c ? `<span class="${c}">${esc(l)}</span>` : esc(l);
    }).join('\n');
    if (atBottom || !pre.dataset.init) { pre.scrollTop = pre.scrollHeight; pre.dataset.init = '1'; }
    document.getElementById('journalInfo').textContent = `${d.log_tail.length} lignes · ${d.finished ? 'terminé' : 'en cours'}`;
  }

  async function tick() {
    try {
      const d = await (await fetch(`/scans/${scanId}/status`, {cache: 'no-store'})).json();
      render(d);
      if (!finished && d.finished) { location.reload(); return; }  // affiche le résumé final une fois
    } catch (e) { /* réseau momentanément coupé : on réessaie au prochain tour */ }
  }

  tick();
  if (!finished) setInterval(tick, 2000);
})();
