    if (l.includes('== Étape')) return l.includes('| ok') ? 'l-ok' : (l.includes('| erreur') ? 'l-err' : 'l-step');
    if (l.includes('!!') || l.includes('Traceback') || l.includes('Error') || l.includes('ERROR')) return 'l-err';
    if (l.startsWith('==')) return 'l-head';
    return '';
