      render(d);
      if (!finished && d.finished) { location.reload(); return; }  // affiche le résumé final une fois
    } catch (e) { /* réseau momentanément coupé : on réessaie au prochain tour */ }
  }

  tick();
  if (!finished) setInterval(tick, 2000);
})();
